"""
PaloRuleSearchSuite_PANORAMA_single.py - BAN GOP 1 FILE DUY NHAT (PANORAMA), TU DONG SINH boi
build_single_file.py tu 3 package DOC LAP check_rule/ (tool CHECK RULE) va
check_ip/ (tool CHECK IP) va check_audit/ (tool CHECK AUDIT) + main logic.
# BAN NAY LA BAN PANORAMA: Panorama IP + Device Group + Target Serial, object thừa kế theo chuỗi DG, rulebase lắp ráp 6 bước 0.3.

KHONG SUA TAY FILE NAY. Moi thay doi logic PHAI sua o dung file component
trong check_rule/*.py hoac check_ip/*.py (KHONG BAO GIO sua ca 2 cung luc cho
1 yeu cau don le), roi chay lai `python tools/build_single.py` de sinh lai file
nay - tranh nhieu nguon code lech nhau qua thoi gian bao tri.

Co che: 3 package check_rule/, check_ip/ va check_audit/ duoc nen (zip) NGUYEN VEN va nhung
vao bien _EMBEDDED_PACKAGES_ZIP_B64 ben duoi (giu nguyen co che import package
chuan cua Python -> 3 tool VAN hoan toan cach ly namespace, KHONG co rui ro
trung ten bien/ham/class du ca 2 package cung dung ten file nhu core.py,
gui.py...). Luc chay, script tu giai ma + insert vao sys.path (zipimport)
TRUOC khi import - khong can giai nen ra dia, khong can file phu nao khac.

Build .exe tu file nay (can PyInstaller: pip install pyinstaller):
    pyinstaller --onefile --noconsole --name PaloRuleSearchSuite \
        PaloRuleSearchSuite_single.py
"""
